<script>import Modal from '../../../components/Modal.svelte';let {onClose,onSave,busy=false}= $props();let file=$state(null);let error=$state('');async function submit(e){e.preventDefault();if(!file){error='Pilih gambar sampul terlebih dahulu.';return;}try{await onSave(file);}catch(err){error=err.message||'Gagal mengunggah sampul.';}}</script>
<Modal title="Ubah Sampul" {onClose}><form onsubmit={submit} class="form-stack"><label for="cover-file">Gambar sampul</label><input id="cover-file" type="file" accept="image/png,image/jpeg,image/webp" onchange={(e)=>file=e.currentTarget.files?.[0]||null} required/><p class="muted small">Gunakan gambar PNG, JPG, atau WebP.</p>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="modal-actions"><button type="button" class="btn btn-light" onclick={onClose}>Batal</button><button class="btn btn-primary" disabled={busy}>{busy?'Mengunggah…':'Unggah sampul'}</button></div></form></Modal>
